//clzcomics.r.sizr.io/core/covers/lg/d7/d7_68890_0_TheLongLongNight.jpg", "listing_type": "raw", "series_slug": "marvel-knights-vol-1", "id": "68890"}, {"sku": "68891", "title": "Marvel Knights, Vol. 1 #13A - No Rest for the Wicked", "series": "Marvel Knights, Vol. 1", "issue": "13A", "story_title": "No Rest for the Wicked", "publisher": "Marvel Comics", "cover_date": "Jul 2001", "edition": "Direct Edition", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Adventure, Super-Heroes", "format": "Comic", "synopsis": "", "upc": "75960604878601311", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/3f/3f_68891_0_NoRestfortheWicked.jpg", "listing_type": "raw", "series_slug": "marvel-knights-vol-1", "id": "68891"}, {"sku": "64856", "title": "Lobo's Back #1A - The Final Fragdown", "series": "Lobo's Back", "issue": "1A", "story_title": "The Final Fragdown", "publisher": "DC Comics", "cover_date": "May 1992", "edition": "Direct Edition", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Adventure, Comedy, Super-Heroes", "format": "Comic", "synopsis": "Everybody's favorite bad boy of comics returns! This time Lobo's taken a job as a skip-tracer, courtesy of his old friend Ramona, the skip-tracing hairdresser who's set him on the trail of his bounty, Loo. That's Loo, the self-proclaimed 'baddest bastich in the galaxy'...who may just be a match for Lobo himself. Yeah, right! LOBO'S BACK is a pulse-pounding, action-packed bonanza of violence, hilarity and more violence, brought to you by the creative team responsible for LOBO: THE LAST CZARNIAN and THE LOBO PARAMILITARY CHRISTMAS SPECIAL: writers Keith Giffen and Alan Grant, and artist Simon Bisley, who provides both interior art and covers. All the covers, because issue #1 features three separate covers, but all three appear on every copy - no fraggin' variant editions here. Strongly and Vehemently Suggested for Mature Readers...so put it back, kid! New Format.", "upc": "", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/e7/e7_64856_0_LobosBack114TheFinalFragdown.jpg", "listing_type": "raw", "series_slug": "lobo-s-back", "id": "64856"}, {"sku": "64741", "title": "Lobo, Vol. 2 #1", "series": "Lobo, Vol. 2", "issue": "1", "story_title": "", "publisher": "DC Comics", "cover_date": "Dec 1993", "edition": "", "story_arc": "The Qigly Affair", "grade": "9.8 Near Mint/Mint", "genre": "Adventure, Super-Heroes", "format": "Comic", "synopsis": "", "upc": "76194120038500111", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/fe/fe_64741_0_LoboVol21TheQiglyAffairPart1.jpg", "listing_type": "raw", "series_slug": "lobo-vol-2", "id": "64741"}, {"sku": "1189075", "title": "Lobo, Vol. 4 #1A", "series": "Lobo, Vol. 4", "issue": "1A", "story_title": "", "publisher": "DC Comics", "cover_date": "May 2026", "edition": "Jorge Corona Regular", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Super-Heroes", "format": "Comic", "synopsis": "SKOTTIE YOUNG AND JORGE CORONA TAKE THE MAIN MAN TO THE NEXT LEVEL! VRRRRROOOOOOMMMMMMMM! The Main Man\u2019s back, baby! And his ride is a motorcycle that moves at the speed of sound, but only if that sound is a rippin\u2019 guitar solo, and you better hop on before he leaves you in the dust with all the bastiches he\u2019s fragged for money or convenience! The Eisner-nominated creative team that brought you a fantastic parable of adolescence in the Midwest, the story of an artist who embraces darkness a little too closely, and the tale of a gunslinger with too much grit to stay buried brings you a classic yarn spun in the star-kissed threads of the cosmic DC Universe. It\u2019s a guts-soaked path from DC K.O. to the end of the universe, where Lobo is going to scratch his name and number in the Source Wall with a cool knife. Don\u2019t miss the mayhem, special guests, or tasty, tasty continuity! Don\u2019t you do it!", "upc": "76194139718400111", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/ef/ef_1189075_0_LoboVol41A.jpg", "listing_type": "raw", "series_slug": "lobo-vol-4", "id": "1189075"}, {"sku": "444357", "title": "Lady Mechanika: The Lost Boys Of West Abbey #2B", "series": "Lady Mechanika: The Lost Boys Of West Abbey", "issue": "2B", "story_title": "", "publisher": "Benitez Productions", "cover_date": "Jun 2016", "edition": "Direct Edition", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "Lady Mechanika's investigation into the deaths of 'undesirable' children in Mechanika City triggers an unexpected reaction from her subconscious self. But are they truly lost memories finally surfacing after so many years, or just simple nightmares?", "upc": "70623833130400821", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/38/38_444357_0_.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-lost-boys-of-west-abbey", "id": "444357"}, {"sku": "504341", "title": "Lady Mechanika Oversized HC #1", "series": "Lady Mechanika Oversized HC", "issue": "1", "story_title": "", "publisher": "Benitez Productions", "cover_date": "", "edition": "", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Fantasy", "format": "Hardcover", "synopsis": "In a steampunk Victorian world filled with flying dirigibles, clockwork automatons, and elegantly fashionable attire, a young woman with mechanical limbs and no memory of how she got them searches desperately for the secrets to her past. This volume collects The Mystery of the Mechanical Corpse, first published in Lady Mechanika #1-5, and also includes the prelude story, The Demon of Satan's Alley, first published in Lady Mechanika #0, all in a special oversized format.", "upc": "9780996603072", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/6e/6e_504341_2_LadyMechanikaOversizedHC1.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-oversized-hc", "id": "504341"}, {"sku": "397689", "title": "Lady Mechanika: The Tablet Of Destinies #1A - Chapter One", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "1A", "story_title": "Chapter One", "publisher": "Benitez Productions", "cover_date": "Apr 2015", "edition": "Joe Benitez Regular Cover", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "After a young friend shows up unexpectedly on her doorstep, Lady Mechanika finds herself on a globe-spanning trek in search of the Tablet of Destinies, an ancient Mesopotamian artifact reputed to hold the knowledge of the gods and the secrets of the universe. Join us for the beginning of an all-new adventure with our favorite steampunk heroine!", "upc": "70623833130400111", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/e5/e5_397689_0_ChapterOne.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "397689"}, {"sku": "903916", "title": "Lady Mechanika: The Tablet Of Destinies #1G - Chapter One", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "1G", "story_title": "Chapter One", "publisher": "Benitez Productions", "cover_date": "Apr 2015", "edition": "", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "After a young friend shows up unexpectedly on her doorstep, Lady Mechanika finds herself on a globe-spanning trek in search of the Tablet of Destinies, an ancient Mesopotamian artifact reputed to hold the knowledge of the gods and the secrets of the universe. Join us for the beginning of an all-new adventure with our favorite steampunk heroine!", "upc": "70623833130400111", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/db/db_903916_0_LadyMechanikaTheTabletOfDestin.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "903916"}, {"sku": "400914", "title": "Lady Mechanika: The Tablet Of Destinies #2A - The Tablet Of Destinies", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "2A", "story_title": "The Tablet Of Destinies", "publisher": "Benitez Productions", "cover_date": "May 2015", "edition": "Direct Edition", "story_arc": "The Tablet Of Destinies", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "In the aftermath of Winifred's abduction, Lady Mechanika's only recourse lies in unraveling the mystery of the fabled Tablet of Destinies. The only clues, however, are a cryptic message and rumors of a notorious secret society - an elite fraternity steeped in mysticism and reputedly impossible to find without an invitation. Will Lady Mechanika succeed in infiltrating their elusive ranks in time to save her young friend?", "upc": "70623833130400211", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/ba/ba_400914_0_ChapterTwo.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "400914"}, {"sku": "404518", "title": "Lady Mechanika: The Tablet Of Destinies #3A - Chapter Three", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "3A", "story_title": "Chapter Three", "publisher": "Benitez Productions", "cover_date": "Jun 2015", "edition": "Joe Benitez Regular Cover", "story_arc": "The Tablet Of Destinies", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "Lady Mechanika journeys to the Continent on rumors that young Winifred was taken to the German countryside and imprisoned in a remote castle. But is the source of these rumors a friend or foe?  And what is his true interest in the Tablet of Destinies? Ships with a cover from Joe Benitez, Martin Montiel and Mike Montiel (cover A) and a cover from Benitez and Peter Steigerwald (cover B).", "upc": "70623833130400311", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/9c/9c_404518_0_ChapterThree.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "404518"}, {"sku": "859171", "title": "Lady Mechanika: The Tablet Of Destinies #4A - The Tablet Of Destinies", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "4A", "story_title": "The Tablet Of Destinies", "publisher": "Benitez Productions", "cover_date": "Aug 2015", "edition": "", "story_arc": "The Tablet Of Destinies", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "Lady Mechanika travels to Africa, the Dark Continent, in search of Winifred's grandfather, but an airship mishap leaves her stranded in the middle of the Sahara. With no food, water, or shelter, how will Lady Mechanika manage in the world's largest and hottest desert? And what will happen to young Winifred? Ships with two covers in a 50/50 distribution.", "upc": "70623833130400411", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/1e/1e_859171_0_.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "859171"}, {"sku": "903910", "title": "Lady Mechanika: The Tablet Of Destinies #5A - Chapter Five", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "5A", "story_title": "Chapter Five", "publisher": "Benitez Productions", "cover_date": "Sep 2015", "edition": "Cover A", "story_arc": "The Tablet Of Destinies", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "Lady Mechanika and Winifred travel deep into the heart of the Congo Jungle in their continued search for Winifred's missing grandfather, but discover that they were not the sole survivors of the airship explosion which left them stranded in the African desert.", "upc": "70623833130400511", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/0a/0a_903910_0_LadyMechanikaTheTabletOfDestin.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "903910"}, {"sku": "418903", "title": "Lady Mechanika: The Tablet Of Destinies #6A - The Tablet Of Destinies", "series": "Lady Mechanika: The Tablet Of Destinies", "issue": "6A", "story_title": "The Tablet Of Destinies", "publisher": "Benitez Productions", "cover_date": "Oct 2015", "edition": "Direct Edition", "story_arc": "The Tablet Of Destinies", "grade": "9.8 Near Mint/Mint", "genre": "Action, Fantasy, Science Fiction", "format": "Comic", "synopsis": "The grand finale of The Tablet of Destinies! Lady Mechanika attempts a daring rescue of the Professor and Winifred, but there may be more at stake than she realized.  What mysterious secret has the Professor uncovered to provoke such extreme measures from the German secret police?  And what will Lady Mechanika do when forced to choose between the lives of her friends and the fate of all humankind?", "upc": "70623833130400611", "price": "", "quantity": "1", "condition_id": "USED", "photo_url": "https://clzcomics.r.sizr.io/core/covers/lg/25/25_418903_0_ChapterSix.jpg", "listing_type": "raw", "series_slug": "lady-mechanika-the-tablet-of-destinies", "id": "418903"}, {"sku": "141756", "title": "Pirates vs Ninjas #1A", "series": "Pirates vs Ninjas", "issue": "1A", "story_title": "", "publisher": "Antarctic Press", "cover_date": "Jan 2007", "edition": "", "story_arc": "", "grade": "9.8 Near Mint/Mint", "genre": "", "format": "Comic", "synopsis": "", "upc": "61072116013800111", "pri